export function getArticle(slug: string): Article {
  const a = ARTICLES[slug];
  if (!a) throw new Error("Unknown article: " + slug);
  return a;
}

/** Build the Next.js Metadata object for an article page. */
export function articleMetadata(slug: string): Metadata {
  const a = getArticle(slug);
  const url = `https://frlegendmodapk.com/${slug}/`;
  return {
    title: a.title,
    description: a.description,
    alternates: { canonical: url },
    openGraph: {
      type: "article",
      siteName: "FR Legends Mod Apk",
      title: a.title,
      description: a.description,
      url,
      images: [{ url: a.image, width: 1200, height: 630 }],
    },
    twitter: {
      card: "summary_large_image",
      title: a.title,
      description: a.description,
      images: [a.image],
    },
  };
}
